INSERT INTO garde_0108 (quoi, lignes, attendu) SELECT 'prix hors formule restants', count(*), 0 FROM armure a JOIN ressource r1 ON r1.id = a.materiau_ligne_id JOIN ressource r2 ON r2.id = a.materiau_colonne_id WHERE a.sorte = 'combinaison' AND a.prix IS NOT (SELECT cout_rf FROM armure_emplacement WHERE id = 'armure-complete') / 100.0 + (SELECT valeur FROM constante_equipement WHERE id = 'armure.unites_par_materiau') * (r1.prix_rf + r2.prix_rf) / 100.0;

DROP TABLE garde_0108;
